import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_ARTICULO, MODELO_TIENDA, TABLA_ARTICULOS } from '../../models/tienda-articulo.model.mjs';

export async function buscarTiendaRepository(tiendaId) {
  const { Item } = await MODELO_TIENDA.build(GetItemCommand)
    .key({ tiendaId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarTiendaRepository(tiendaId, minimo) {
  const { Items = [] } = await TABLA_ARTICULOS.build(QueryCommand)
    .entities(MODELO_ARTICULO)
    .query({ index: 'PorTienda', partition: tiendaId })
    .options({ filters: { Articulo: { attr: 'stock', gte: minimo } } })
    .send();
  return Items;
}
